const filmIcon=(paths)=>'<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths+'</svg>';
const filmIcons={play:filmIcon('<path d="m8 5 11 7-11 7z"/>'),pause:filmIcon('<path d="M8 5v14M16 5v14" stroke-width="3"/>'),sound:filmIcon('<path d="m11 5-5 4H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M19 5a10 10 0 0 1 0 14"/>'),mute:filmIcon('<path d="m11 5-5 4H3v6h3l5 4z"/><path d="m16 9 5 6m0-6-5 6"/>')};
function playLabel(card,playing){const b=card.querySelector('[data-film-play]');b.innerHTML=playing?filmIcons.pause:filmIcons.play;b.setAttribute('aria-label',(playing?'Pause ':'Play ')+card.dataset.title);b.title=playing?'Pause':'Play'}
const filmCards=[...document.querySelectorAll('.film-card[data-kind="video"]')];
const allFilmCards=[...document.querySelectorAll('.film-card')];
const reducedFilmMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const filmFinePointer=matchMedia('(hover:hover) and (pointer:fine)').matches;
const filmState=new Map(filmCards.map(card=>[card,{manualPaused:false,manualStarted:false,wanted:false,pending:false,generation:0,resumeTime:0,mutedByUser:false,audioBlocked:false,visible:false}]));
let activeFilm=null,filmFrame=0,leavingGallery=false;
function soundLabel(card,on=false){const b=card.querySelector('[data-film-sound]');b.innerHTML=on?filmIcons.sound:filmIcons.mute;b.setAttribute('aria-pressed',String(on));const label=card.dataset.audio==='false'?'Silent video':on?'Mute':'Unmute';b.setAttribute('aria-label',label+' '+card.dataset.title);b.title=label;card.classList.toggle('audible',on)}
function muteFilm(card){card.querySelector('video').muted=true;soundLabel(card,false)}
function soundFor(card,gesture=false){const s=filmState.get(card),v=card.querySelector('video');if(gesture)s.audioBlocked=false;const on=card===activeFilm&&card.dataset.audio!=='false'&&!s.mutedByUser&&!s.audioBlocked;v.muted=!on;soundLabel(card,on);if(on)filmCards.forEach(c=>{if(c!==card)muteFilm(c)})}
function filmGeometry(card){const r=card.querySelector('.film-screen').getBoundingClientRect();const width=Math.max(0,Math.min(r.right,innerWidth)-Math.max(r.left,0));const height=Math.max(0,Math.min(r.bottom,innerHeight)-Math.max(r.top,0));return{visible:!card.hidden&&width>0&&height>=Math.min(90,r.height*.15),far:card.hidden||r.bottom<-innerHeight||r.top>innerHeight*2,score:width*height,distance:Math.abs((r.top+r.bottom)/2-innerHeight/2)}}
function loadFilm(card){const v=card.querySelector('video');if(!v.getAttribute('src')){v.preload='auto';v.src=v.dataset.src;v.load()}return v}
async function playFilm(card,gesture=false){const s=filmState.get(card);if(leavingGallery||document.hidden||!filmGeometry(card).visible||s.manualPaused)return;const v=loadFilm(card);s.wanted=true;card.dataset.visible='true';soundFor(card,gesture);if(!v.paused||s.pending)return;s.pending=true;const generation=s.generation;try{await v.play();if(generation!==s.generation||!s.wanted||s.manualPaused||leavingGallery)v.pause()}catch(error){if(generation!==s.generation||!s.wanted)return;if(error.name==='NotAllowedError'&&!v.muted){s.audioBlocked=true;muteFilm(card);try{await v.play()}catch{playLabel(card,false)}}else if(error.name!=='AbortError'){card.classList.add('needs-play');playLabel(card,false)}}finally{if(generation===s.generation)s.pending=false}}
function stopFilm(card,unload=false){const s=filmState.get(card),v=card.querySelector('video');if(s.wanted||s.pending||!v.paused){s.generation++;s.pending=false;s.wanted=false;v.pause()}muteFilm(card);if(unload&&v.getAttribute('src')){s.resumeTime=Number.isFinite(v.currentTime)?v.currentTime:0;s.generation++;s.pending=false;v.removeAttribute('src');v.preload='none';v.load()}playLabel(card,false)}
function reconcileFilms(){filmFrame=0;if(leavingGallery)return;const geometry=new Map(filmCards.map(c=>[c,filmGeometry(c)]));const candidates=filmCards.filter(c=>{const s=filmState.get(c),g=geometry.get(c);s.visible=g.visible; c.dataset.visible=String(g.visible);return g.visible&&!s.manualPaused&&(!reducedFilmMotion||s.manualStarted)&&!document.hidden}).sort((a,b)=>(Number(b===activeFilm)-Number(a===activeFilm))||(Number(filmState.get(b).manualStarted)-Number(filmState.get(a).manualStarted))||geometry.get(b).score-geometry.get(a).score);const selected=new Set(candidates.slice(0,4));filmCards.forEach(c=>{if(selected.has(c))playFilm(c);else stopFilm(c,geometry.get(c).far)});}
function scheduleFilms(){if(!filmFrame&&!leavingGallery)filmFrame=requestAnimationFrame(reconcileFilms)}
function activateFilm(card,gesture=false){activeFilm=card;const s=filmState.get(card);s.mutedByUser=false;if(gesture)s.audioBlocked=false;filmCards.forEach(c=>{if(c!==card)muteFilm(c)});soundFor(card,gesture);if(!s.manualPaused&&(!reducedFilmMotion||s.manualStarted))playFilm(card,gesture);scheduleFilms()}
filmCards.forEach(card=>{const s=filmState.get(card),v=card.querySelector('video'),play=card.querySelector('[data-film-play]'),sound=card.querySelector('[data-film-sound]');playLabel(card,false);soundLabel(card,false);
 card.addEventListener('pointerenter',ev=>{if(ev.pointerType!=='touch')activateFilm(card)});
 card.addEventListener('pointerleave',ev=>{if(ev.pointerType!=='touch'){muteFilm(card);if(activeFilm===card)activeFilm=null}});
 card.addEventListener('focusin',ev=>{if(filmFinePointer&&ev.target.matches(':focus-visible'))activateFilm(card)});
 card.addEventListener('focusout',ev=>{if(!card.contains(ev.relatedTarget)){muteFilm(card);if(activeFilm===card)activeFilm=null}});
 play.addEventListener('click',()=>{if(!v.paused){s.manualPaused=true;s.manualStarted=false;card.dataset.userPaused='true';stopFilm(card)}else{s.manualPaused=false;s.manualStarted=true;card.dataset.userPaused='false';playFilm(card,true)}scheduleFilms()});
 sound.addEventListener('click',()=>{if(!v.muted){s.mutedByUser=true;muteFilm(card)}else{activateFilm(card,true)}});
 v.addEventListener('click',()=>{if(v.paused){s.manualPaused=false;s.manualStarted=true;card.dataset.userPaused='false';playFilm(card,true)}if(v.muted)activateFilm(card,true);else if(!filmFinePointer){s.mutedByUser=true;muteFilm(card)}});
 v.addEventListener('loadedmetadata',()=>{if(s.resumeTime>0&&s.resumeTime<v.duration){try{v.currentTime=s.resumeTime}catch{}}s.resumeTime=0;scheduleFilms()});
 v.addEventListener('canplay',()=>{if(s.wanted&&!s.manualPaused&&!s.pending&&v.paused)playFilm(card)});
 v.addEventListener('playing',()=>{if(!s.wanted||s.manualPaused||leavingGallery){v.pause();return}playLabel(card,true);card.classList.remove('needs-play','media-error');card.querySelector('.film-error').hidden=true});
 v.addEventListener('pause',()=>playLabel(card,false));
 v.addEventListener('error',()=>{if(!v.getAttribute('src'))return;card.classList.add('media-error');card.querySelector('.film-error').hidden=false;playLabel(card,false);s.pending=false});
 v.addEventListener('volumechange',()=>{if(!v.muted&&(activeFilm!==card||card.dataset.audio==='false'))muteFilm(card)});
 const variants=JSON.parse(card.dataset.variants||'[]');let index=0;
 function changeVariant(next){index=(next+variants.length)%variants.length;stopFilm(card,true);const item=variants[index];s.resumeTime=0;v.dataset.src=item.video;v.poster=item.poster;v.width=item.width;v.height=item.height;card.querySelector('.film-screen').style.setProperty('--frame-ratio',item.width+'/'+item.height);card.querySelector('[data-variant-count]').textContent=(index+1)+' / '+variants.length;scheduleFilms()}
 if(variants.length){card.querySelector('[data-variant-prev]').addEventListener('click',()=>changeVariant(index-1));card.querySelector('[data-variant-next]').addEventListener('click',()=>changeVariant(index+1));v.addEventListener('ended',()=>{if(s.wanted&&!s.manualPaused)changeVariant(index+1)})}
 let hideControls;card.addEventListener('pointerdown',ev=>{if(ev.pointerType==='touch'){card.classList.add('show-controls');clearTimeout(hideControls);hideControls=setTimeout(()=>card.classList.remove('show-controls'),2500)}});
});
// Re-evaluate actual screen rectangles; multicolumn layouts can yield stale observer entries.
if('IntersectionObserver' in window){const observer=new IntersectionObserver(scheduleFilms,{rootMargin:'100px',threshold:[0,.15,.5,1]});filmCards.forEach(c=>observer.observe(c.querySelector('.film-screen')))}
if('ResizeObserver' in window){const observer=new ResizeObserver(scheduleFilms);document.querySelectorAll('.film-grid,.film-screen').forEach(e=>observer.observe(e))}
window.addEventListener('scroll',scheduleFilms,{passive:true});window.addEventListener('resize',scheduleFilms,{passive:true});document.querySelectorAll('.film-card img').forEach(img=>img.addEventListener('load',scheduleFilms));
document.addEventListener('visibilitychange',()=>{if(document.hidden){filmCards.forEach(c=>stopFilm(c));activeFilm=null}else scheduleFilms()});
function releaseGallery(){leavingGallery=true;if(filmFrame)cancelAnimationFrame(filmFrame);filmFrame=0;activeFilm=null;filmCards.forEach(c=>stopFilm(c,true))}
document.addEventListener('click',event=>{if(event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const a=event.target.closest('a[href]');if(!a||a.target==='_blank'||a.hasAttribute('download'))return;const url=new URL(a.href,location.href);if(url.origin===location.origin&&(url.pathname!==location.pathname||url.search!==location.search))releaseGallery()},{capture:true});
window.addEventListener('pagehide',releaseGallery);window.addEventListener('pageshow',()=>{leavingGallery=false;scheduleFilms()});
allFilmCards.filter(c=>c.dataset.kind==='image').forEach(card=>{const slides=JSON.parse(card.dataset.slides),img=card.querySelector('.film-image');let index=0;function setFrame(i){index=(i+slides.length)%slides.length;img.src=slides[index].image;img.alt=card.dataset.title+' ? image '+(index+1);card.querySelector('[data-frame-count]').textContent=(index+1)+' / '+slides.length;scheduleFilms()}card.querySelector('[data-frame-prev]').addEventListener('click',()=>setFrame(index-1));card.querySelector('[data-frame-next]').addEventListener('click',()=>setFrame(index+1))});
const watchFilters=[...document.querySelectorAll('[data-watch-filter]')];watchFilters.forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.watchFilter;watchFilters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let total=0;allFilmCards.forEach(c=>{c.hidden=value!=='All'&&c.dataset.client!==value;if(c.hidden&&c.dataset.kind==='video')stopFilm(c,true);if(!c.hidden)total++});const status=document.querySelector('.watch-count');if(status)status.textContent=total+' '+(total===1?'piece':'pieces')+(value==='All'?'':' / '+value);activeFilm=null;scheduleFilms()}));
scheduleFilms();
